def P(text, style=BODY): return Paragraph(text, style)
def section(title): return [P(title, H1)]
def subsection(title): return [P(title, H2)]
def issue(code, sev, title, desc, evidence='R'):
    color = {'P0':'#b91c1c','P1':'#c2410c','P2':'#b45309','P3':'#4b5563'}[sev]
    label = f'<font color="{color}"><b>[{sev}] {code} · {title}</b></font> '
    mark = '<b>【已验证】</b> ' if evidence == 'E' else '<b>【逻辑推演，需复测】</b> '
    return P(label + mark + desc, ISSUE)
def footer(canvas, doc):
    canvas.saveState(); canvas.setStrokeColor(colors.HexColor('#fed7aa')); canvas.line(18*mm,15*mm,W-18*mm,15*mm)
    canvas.setFont('ShopSans',7.5); canvas.setFillColor(colors.HexColor('#6b7280'))
    canvas.drawString(18*mm,10*mm,'商城三端深度测试分析 · 2026-09-06 · 仅限测试与整改使用')
    canvas.drawRightString(W-18*mm,10*mm,f'第 {doc.page} 页'); canvas.restoreState()

story=[]
story += [Spacer(1,36*mm),P('商城小程序端、运营管理后台、商户后台',TITLE),P('完整深度测试分析报告',TITLE),P('报告日期：2026-09-06　|　方法：后台只读界面核查 + 小程序运行态观察 + 业务逻辑/状态机推演',SUB),Spacer(1,12*mm),P('<b>结论摘要</b>：当前系统已具备商品、订单、支付、退款及多类商家营销配置的基础骨架；但运营后台缺失用户、优惠券、营销配置、角色权限、结算等平台治理入口，且已观察到跨端订单类型不一致。营销规则缺少统一的“价格引擎/叠加矩阵”治理，零价订单与活动并发、缓存失效、退款回补均存在高风险。建议先冻结高风险营销上线范围，补齐规则中心、审计和对账后再扩量。',BOX),Spacer(1,5*mm),P('阅读说明',H2),P('【已验证】来自 2026-09-06 的登录后页面、表格、配置提示或小程序运行态；未点击会产生外部副作用的“发货、保存、停止、立即对账”等操作。【逻辑推演，需复测】基于已见功能、交易状态机及题设场景形成，不表述为已发生缺陷。严重度：P0 资金/越权或数据破坏；P1 主要业务中断或高概率损失；P2 体验/运营效率；P3 可用性优化。',SMALL),PageBreak()]

