story += [P('本轮未运行、修改或部署代码；未提交订单、支付、退款、发货或活动保存。运营后台以 admin 账户、商户后台以 merchant01 账户登录；小程序以开发工具已有运行态进行页面观察。因未接入弱网代理、接口抓包、真实微信支付和多角色账号，相关结论已明确标为待复测。',BODY),P('已验证系统能力 / 缺口',H2),P('运营端菜单：经营概览、商家、分类、订单、支付、退款、Banner、商品审核、操作日志、微信设置；未见用户管理、平台优惠券、平台营销活动、角色权限、结算/分账、消息通知入口。商户端菜单：店铺/分类/商品/Banner/订单/退款/账号与权限，以及通用券、复购券、秒杀、预售、满减满折、邀请、积分会员日、搭配购、抽奖盲盒。',BODY),P('已验证的高优先级事实',H2),
issue('X-01','P0','跨端订单类型不一致','订单 26090601030300611294 在运营后台“平台订单”中显示类型为“搭配购”，同订单在 merchant01 的“订单发货”中显示为“普通”；若类型驱动售后、佣金、税率、营销成本或履约规则，将造成错审、错账或漏补偿。应以订单行快照中的 canonical orderType 为唯一来源，三端通过同一枚举展示，并加跨端契约测试。','E'),
issue('X-02','P0','零价成交样本未被前台风险拦截','小程序订单列表存在“实付 ¥0”的待发货订单，运营/商户首页也存在 ¥0.01 测试性已支付订单；目前未看到零价订单审批、原因标签或金额异常告警。若零价由价格、优惠叠加或库存活动配置意外产生，可被批量刷单、薅券和消耗库存。','E'),
issue('O-01','P1','运营端平台治理功能缺口','运营菜单未提供用户、平台券、平台营销、角色权限、结算/分账和消息通知管理；无法完成题设要求的“平台管理员配置后在小程序生效”的可审计闭环。','E'),
issue('M-01','P1','营销规则呈分散配置，缺少全局冲突面','商户后台将券、秒杀、预售、满减、邀请、积分、搭配购、抽奖拆分为多个页面；已知秒杀“不参与优惠券”、满减“高优先级优先命中”，但未见跨活动的可配置/可预览叠加矩阵。','E'),PageBreak()]

story += section('1. 【小程序C端发现问题&风险点】')
story += subsection('1.1 功能闭环问题')
for x in [
('C-01','P1','登录前后身份切换与资料清理','游客浏览、登录、退出再切换账户时，购物车、地址、券、积分、待支付订单必须按 userId 隔离。若仅清 token 不清本地购物车/券列表，B 用户会看到或使用 A 用户权益，构成隐私与资金风险。退出登录后应清敏感缓存、保留仅匿名推荐缓存并加 userId 命名空间。'),
('C-02','P1','下单最终价缺少服务端二次确认','商品详情/购物车显示价、活动价、券、积分抵扣和运费只能用于展示；提交订单必须返回“报价版本号+服务端明细”。若仍信任前端金额或旧活动价，快速切换 SKU、活动结束、后台改价后会以过期价成交。'),
('C-03','P1','重复提交和支付回调幂等','用户连续点“提交订单”、从支付页返回并再次提交、弱网重试时，必须以 clientRequestId 做订单创建幂等，以支付单号做支付回调幂等。否则会产生两张待支付单、重复扣活动库存或重复发复购券/积分。'),
('C-04','P1','售后状态机缺少完整约束','仅“申请退款”不足以覆盖退款、退货退款、商家拒绝、用户举证、退货物流、商家验货、平台介入、原路退款、退款失败重试、部分退款和不可再次申请。每个订单行应记录可退数量/金额与已退金额；否则多次售后可突破实付金额。'),
('C-05','P2','无地址/无订单/无券空态需可行动','无收货地址结算应阻断并直达新增地址；无订单、无券、无收藏应有解释和下一步入口。小程序当前购物车空态已具备“去逛逛/猜你喜欢”，但地址、售后、券过期/不可用的空态仍需逐页验证。'),
('C-06','P1','预售与拼团订单的履约门槛','预售必须在“尾款支付成功”前禁止发货和普通退款；拼团必须在成团前禁止发货，超时未成团自动退资金且不得重复退。小程序已展示预售“查看预售”和待成团标签，需验证从活动页、订单页、商户履约页均引用同一状态机。'),
('C-07','P2','小程序订单删除语义','已取消订单显示“删除”。应仅做用户侧隐藏、保留后台/财务审计记录，并提示“不可恢复、不影响退款/对账记录”；若物理删除，会破坏支付、退款和营销核销链路。')]: story.append(issue(*x,'R'))
story += subsection('1.2 UI / 页面布局与样式问题')
for x in [
('C-UI-01','P2','首页营销密度过高','运行态首页同屏/首屏连续出现预售、积分商城、会员日、抽奖、分类、推荐、拼团、秒杀；每个模块都携带“去参与/立即预订”动作。无用户分层和频控会挤压搜索与商品发现，使低意图用户误触或忽略核心购买路径。建议每屏最多一个强 CTA，其他营销聚合为可折叠“活动会场”。'),
('C-UI-02','P2','倒计时和活动结束态需一致','首页有“距结束 01:45:59”的秒杀卡。结束后应同步变为“已结束/下一场”、置灰主按钮、禁止跳转到可下单详情；客户端倒计时只能展示，不能作为资格判断。延期/提前结束需展示服务器时间与更新时间，避免用户看到倒计时未结束却下单失败。'),
('C-UI-03','P2','零价/超低价视觉警示不足','小程序订单列表已出现实付 ¥0、多个 ¥0.01 订单。即便是合法试运营价格，页面也应标明“活动优惠后/测试价/已减免明细”，并在结算页显示原价、优惠、运费、实付四段式账单；否则用户及客服无法判别异常金额。'),
('C-UI-04','P2','商品卡片信息截断风险','首页/分类页商品名普遍较长，价格与促销标签并列。应限定两行、省略号、固定图片区比例与最低 44px 热区；服务类商品还需显著显示核销/到店属性，避免与实物混在同一“发货”心智。'),
('C-UI-05','P3','加载、错误与离线页缺少验收证据','本轮无法人工注入慢网，不能证明 skeleton、重试、离线缓存提示、图片加载失败占位和列表分页尾部状态。必须以 iPhone SE/标准机/大屏、横竖安全区和 2G/断网脚本做视觉回归。')]: story.append(issue(*x,'E' if x[0] in ['C-UI-01','C-UI-02','C-UI-03'] else 'R'))
